(() => {
  const root = document.querySelector('#gpu-captures');
  if (!root) return;
  const base = '/gpu-sharing/results/';
  const modes = [
    ['Default', 'run-02-core/ts-default', 'AB'],
    ['Short', 'inference-extension-20261025/inference-ts-short', 'AB'],
    ['Long', 'inference-extension-20261025/inference-ts-long', 'AB'],
    ['MPS 25%', 'inference-extension-20261025/inference-mps25', 'AB'],
    ['MPS 50%', 'run-02-core/mps50', 'AB'],
    ['MPS 100%', 'inference-extension-20261025/inference-mps100', 'AB'],
    ['MIG', 'run-02-core/mig', 'AB'],
    ['Solo', 'inference-extension-20261025/inference-solo', 'A']
  ];
  const controls = root.querySelector('.gpu-modes');
  const output = root.querySelector('pre code');
  const source = root.querySelector('.gpu-source');
  const status = root.querySelector('[role=status]');

  for (const [name, path, active] of modes) {
    const button = document.createElement('button');
    button.type = 'button'; button.textContent = name;
    button.setAttribute('aria-pressed', 'false');
    button.addEventListener('click', () => {
      for (const b of controls.children) b.setAttribute('aria-pressed', String(b === button));
      const url = base + path + '/1024-1024-c5-r0-' + active + '/during-nvidia-smi.txt';
      if (source) source.href = url;
      output.textContent = GPU_CAPTURE_TEXT[name];
      status.textContent = '';
      root.querySelector('pre').scrollLeft = 0;
    });
    controls.append(button);
  }
  controls.firstElementChild.click();
})();
